// Regenerates tests/fixtures/appAttest/attestations.json: attestation objects with the same structure
// Apple's App Attest produces, but chained to a throwaway "Fixture App Attest Root" instead of Apple's
// root, so the full attestation path can be tested without a device. Needs the openssl CLI.
//   node tests/fixtures/appAttest/generate.mjs
import crypto from "node:crypto";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { fileURLToPath } from "node:url";
import { encodeCbor } from "../../helpers/cbor.js";
import { createChallengeSigner, DEFAULT_APP_ID } from "../../../src/backend/services/appAttest.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "app-attest-fixture-"));
const file = (name) => path.join(dir, name);
const openssl = (...args) => execFileSync("openssl", args, { cwd: dir, stdio: ["ignore", "pipe", "pipe"] });
const sha256 = (data) => crypto.createHash("sha256").update(data).digest();

const SECRET = "fixture-device-challenge-secret-0123456789";
// After the certificates' notBefore (they are created now), so tests can pin "now" to this moment.
const ISSUED_AT = Math.ceil(Date.now() / 1000) * 1000 + 120_000;

openssl("ecparam", "-name", "secp384r1", "-genkey", "-noout", "-out", "root.key");
openssl("req", "-x509", "-new", "-key", "root.key", "-subj", "/CN=Fixture App Attest Root", "-days", "36500",
  "-addext", "basicConstraints=critical,CA:TRUE", "-addext", "keyUsage=critical,keyCertSign,cRLSign", "-out", "root.pem");
openssl("ecparam", "-name", "secp384r1", "-genkey", "-noout", "-out", "inter.key");
openssl("req", "-new", "-key", "inter.key", "-subj", "/CN=Fixture App Attest CA 1", "-out", "inter.csr");
fs.writeFileSync(file("ca.cnf"), "[v3]\nbasicConstraints=critical,CA:TRUE,pathlen:0\nkeyUsage=critical,keyCertSign,cRLSign\n");
openssl("x509", "-req", "-in", "inter.csr", "-CA", "root.pem", "-CAkey", "root.key", "-CAcreateserial", "-days", "36500",
  "-extfile", "ca.cnf", "-extensions", "v3", "-out", "inter.pem");

const signer = createChallengeSigner({ secret: SECRET, now: () => ISSUED_AT });

function attestationFor(aaguid, label) {
  const { privateKey, publicKey } = crypto.generateKeyPairSync("ec", { namedCurve: "P-256" });
  const jwk = publicKey.export({ format: "jwk" });
  const x = Buffer.from(jwk.x, "base64url");
  const y = Buffer.from(jwk.y, "base64url");
  const keyIdBytes = sha256(Buffer.concat([Buffer.from([4]), x, y]));
  const { challenge } = signer.issue();

  const cose = encodeCbor(new Map([[1, 2], [3, -7], [-1, 1], [-2, x], [-3, y]]));
  const counter = Buffer.alloc(4);
  const idLength = Buffer.alloc(2);
  idLength.writeUInt16BE(32);
  const authData = Buffer.concat([sha256(DEFAULT_APP_ID), Buffer.from([0x40]), counter, aaguid, idLength, keyIdBytes, cose]);
  const nonce = sha256(Buffer.concat([authData, sha256(Buffer.from(challenge, "utf8"))]));

  fs.writeFileSync(file(`${label}.key`), privateKey.export({ type: "pkcs8", format: "pem" }));
  openssl("req", "-new", "-key", `${label}.key`, "-subj", `/CN=${keyIdBytes.toString("hex")}`, "-out", `${label}.csr`);
  const ext = `30:24:a1:22:04:20:${nonce.toString("hex").match(/../g).join(":")}`;
  fs.writeFileSync(file(`${label}.cnf`), `[v3]\nbasicConstraints=critical,CA:FALSE\nkeyUsage=critical,digitalSignature\n1.2.840.113635.100.8.2=DER:${ext}\n`);
  openssl("x509", "-req", "-in", `${label}.csr`, "-CA", "inter.pem", "-CAkey", "inter.key", "-CAcreateserial", "-days", "36500",
    "-extfile", `${label}.cnf`, "-extensions", "v3", "-outform", "DER", "-out", `${label}.der`);
  const interDer = openssl("x509", "-in", "inter.pem", "-outform", "DER");

  const attestation = encodeCbor({
    fmt: "apple-appattest",
    attStmt: { x5c: [fs.readFileSync(file(`${label}.der`)), interDer], receipt: Buffer.from("fixture-receipt") },
    authData,
  });
  return {
    keyId: keyIdBytes.toString("base64"),
    challenge,
    attestation: attestation.toString("base64"),
    privateKeyPem: privateKey.export({ type: "pkcs8", format: "pem" }),
  };
}

const fixture = {
  note: "Generated by generate.mjs. Throwaway keys and a fixture root, not Apple's. Never trust this root in production.",
  appId: DEFAULT_APP_ID,
  secret: SECRET,
  issuedAt: new Date(ISSUED_AT).toISOString(),
  rootPem: fs.readFileSync(file("root.pem"), "utf8"),
  production: attestationFor(Buffer.concat([Buffer.from("appattest"), Buffer.alloc(7)]), "prod"),
  development: attestationFor(Buffer.from("appattestdevelop"), "dev"),
};
fs.writeFileSync(path.join(here, "attestations.json"), `${JSON.stringify(fixture, null, 2)}\n`);
fs.rmSync(dir, { recursive: true, force: true });
console.log("wrote attestations.json");
